import arrow
from datetime import date
from typing import Optional


def create_arrow_from_date(date: str, tzinfo: Optional[str] = None) -> str:
    """Create an Arrow object from a date string and optional timezone. date: A date string in YYYY-MM-DD format, e.g. '2023-10-15' -> Arrow object at 2023-10-15 00:00:00+00:00. tzinfo: (optional) A timezone expression. Defaults to UTC."""
    try:
        # Parse the date string into a date object
        year, month, day = map(int, date.split('-'))
        date_obj = date(year, month, day)

        # Create Arrow object using fromdate classmethod
        if tzinfo is None:
            arrow_obj = arrow.Arrow.fromdate(date_obj)
        else:
            arrow_obj = arrow.Arrow.fromdate(date_obj, tzinfo)

        # Return string representation of the Arrow object
        return str(arrow_obj)

    except ValueError as e:
        raise ValueError(f"Invalid date format or timezone: {date!r}, {tzinfo!r}") from e
    except Exception as e:
        raise ValueError(f"Failed to create Arrow object: {str(e)}") from e

