def get_time_span(frame: str, count: int = 1, bounds: str = "[)") -> Union[Tuple[str, str], None]:
    """Get the start and end of a time span for a given frame. frame: The timeframe to span (year, quarter, month, week, day, hour, minute, second). count: The number of frames to span. bounds: A string specifying whether to include or exclude start and end values ('()', '(]', '[)', or '[]'). Returns a tuple of start and end timestamps as strings."""
