import arrow
from typing import Union, Any


def round_down_time(arrow_object: Any, frame: str, week_start: int = 1) -> str:
    """Returns a new Arrow object rounded down to the beginning of a specified timeframe.

    Args:
        arrow_object: An Arrow object to round down
        frame: The timeframe to round down to (e.g., 'hour', 'day', 'week')
        week_start: Only used with 'week' frame. Monday is 1, Sunday is 7

    Returns:
        A string representation of the Arrow object representing the floor of the timespan

    Example:
        >>> import arrow
        >>> arrow.utcnow().floor('hour')
        <Arrow [2013-05-09T03:00:00+00:00]>
    """
    try:
        # Convert to Arrow object if it's a string representation
        if isinstance(arrow_object, str):
            # Try to parse the string as an Arrow object
            try:
                arrow_obj = arrow.get(arrow_object)
            except Exception:
                raise ValueError(f"Invalid arrow object string: {arrow_object}")
        else:
            arrow_obj = arrow_object

        if frame == 'week':
            result = arrow_obj.floor(frame, week_start=week_start)
        else:
            result = arrow_obj.floor(frame)

        return str(result)
    except Exception as e:
        raise ValueError(f"Failed to round down time: {str(e)}")

import arrow
from typing import Literal, Dict, Any


def check_time_range(target: Dict[str, Any], start: Dict[str, Any], end: Dict[str, Any], bounds: Literal['()', '(]', '[)', '[]'] = '()') -> bool:
    """Check if an Arrow object falls within a specified time range.

    :param target: A dictionary containing datetime components (year, month, day, etc.) representing the time to check
    :param start: A dictionary containing datetime components (year, month, day, etc.) representing the start of the time range
    :param end: A dictionary containing datetime components (year, month, day, etc.) representing the end of the time range
    :param bounds: (optional) a string specifying whether to include or exclude the start and end values ('()', '(]', '[)', or '[]')

    Example:
    >>> start = {'year': 2013, 'month': 5, 'day': 5, 'hour': 12, 'minute': 30, 'second': 10}
    >>> end = {'year': 2013, 'month': 5, 'day': 5, 'hour': 12, 'minute': 30, 'second': 36}
    >>> target = {'year': 2013, 'month': 5, 'day': 5, 'hour': 12, 'minute': 30, 'second': 27}
    >>> check_time_range(target, start, end)
    True
    """
    try:
        # Create Arrow objects from dictionaries
        target_arrow = arrow.Arrow(**target)
        start_arrow = arrow.Arrow(**start)
        end_arrow = arrow.Arrow(**end)

        return target_arrow.is_between(start_arrow, end_arrow, bounds)
    except Exception as e:
        raise ValueError(f"Error checking time range: {str(e)}")

