def extract_date_component(year: int, month: int, day: int, hour: Optional[int] = 0, minute: Optional[int] = 0, second: Optional[int] = 0, microsecond: Optional[int] = 0) -> dict[str, int]:
    """Extract the date component from an Arrow object. year: The year component of the date, month: The month component of the date, day: The day component of the date, hour: The hour component of the time, minute: The minute component of the time, second: The second component of the time, microsecond: The microsecond component of the time."""
    try:
        arrow_obj = arrow.arrow.Arrow(year, month, day, hour, minute, second, microsecond)
        date_obj = arrow_obj.date()
        return {"year": date_obj.year, "month": date_obj.month, "day": date_obj.day}
    except Exception as e:
        raise ValueError(f"Failed to create Arrow object: {str(e)}")

