def format_ctime(year: int, month: int, day: int, hour: Optional[int] = 0, minute: Optional[int] = 0, second: Optional[int] = 0, microsecond: Optional[int] = 0, tzinfo: Optional[str] = None) -> str:
    """Format an Arrow object as a ctime string. year: The year, month: The month, day: The day, hour: The hour (optional), minute: The minute (optional), second: The second (optional), microsecond: The microsecond (optional), tzinfo: The timezone info (optional). Example: format_ctime(2019, 1, 19, 18, 26, 50) -> 'Sat Jan 19 18:26:50 2019'."""
