        if tzinfo is not None:
            dt = arrow.arrow.Arrow(year, month, day, hour, minute, second, microsecond, tzinfo)
        else:
            dt = arrow.arrow.Arrow(year, month, day, hour, minute, second, microsecond)
        return dt.ctime()
    except Exception as e:
        raise ValueError(f"Failed to format ctime: {str(e)}")

import arrow
from typing import Union


def format_with_strftime(arrow_object: Union[arrow.Arrow, str], format: str) -> str:
    """Format an Arrow object using strftime-style formatting.

    :param arrow_object: An Arrow object to format
    :param format: The strftime-style format string

    Usage::

        >>> arrow.utcnow().strftime('%d-%m-%Y %H:%M:%S')
        '23-01-2019 12:28:17'
    """
    if isinstance(arrow_object, str):
        try:
            # Try to parse the string as an Arrow object
            arrow_obj = arrow.get(arrow_object)
        except Exception as e:
            raise ValueError(f"Invalid arrow string: {arrow_object!r}") from e
    else:
        arrow_obj = arrow_object

    try:
        return arrow_obj.strftime(format)
    except Exception as e:
        raise ValueError(f"Failed to format arrow object with format {format!r}: {str(e)}") from e

import arrow
from typing import Optional


def factory_parse_date(date_string: str, tzinfo: Optional[str] = None) -> str:
    """Parse a date string into an Arrow object using the factory method.

    :param date_string: A date string to parse into an Arrow object
    :param tzinfo: A timezone expression to replace the timezone
    :return: String representation of the parsed Arrow object

    Example:
        >>> factory_parse_date('2023-01-01', 'US/Eastern')
        '2023-01-01T00:00:00+00:00'
    """
    try:
        if tzinfo is not None:
            result = arrow.factory.ArrowFactory().get(date_string, tzinfo=tzinfo)
        else:
            result = arrow.factory.ArrowFactory().get(date_string)
        return str(result)
    except Exception as e:
        raise ValueError(f"Failed to parse date string '{date_string}': {str(e)}")
